Fixpoint ox1 (jt : list byte) (cells : list (option deltX1)) : list byte :=
  match cells, jt with
  | o :: cs, b0 :: b1 :: jt' =>
      (match o with Some c => Z_to_bv 8 (x1_nbBits c) | None => b0 end)
      :: (match o with Some c => Z_to_bv 8 (x1_byte c) | None => b1 end) :: ox1 jt' cs
  | _, _ => jt
  end.

