(* [comment removed for export] *)
Lemma ox1_prefix : forall k cells jt, (k <= length cells)%nat -> length jt = (2 * length cells)%nat ->
  (forall i, (i < k)%nat -> exists c, nth i cells None = Some c) ->
  firstn (2 * k) (ox1 jt cells) = firstn (2 * k) (x1_bytes (x1_cells cells)).
Proof.
