Lemma fill_syms_step : forall fuel s cnt sym len nb syms cells u, s < cnt ->
  fill_syms (S fuel) s cnt sym len nb syms cells u =
    let! b := oload syms (sym + s) in
    let! cells' := fill_cells (Z.to_nat len) cells u (mkX1 nb b) in
    fill_syms fuel (s + 1) cnt sym len nb syms cells' (u + len).
Proof.
