Lemma fill_weights_S : forall fuel w tl rank syms cells sym rs,
  fill_weights (S fuel) w tl rank syms cells sym rs =
    let! symbolCount := load rank w in
    let! p := shl32 1 w in
    let length := p / 2 in
    let nbBits := to_byte (tl + 1 - w) in
    let! r := fill_syms (S (Z.to_nat symbolCount)) 0 symbolCount sym length nbBits syms cells rs in
    let '(cells', _) := r in
    fill_weights fuel (w + 1) tl rank syms cells' (sym + symbolCount) (rs + symbolCount * length).
Proof.
