Lemma rank_start_S : forall fuel n next rank rs,
  rank_start_loop (S fuel) n next rank rs =
    let! v := load rank n in let! rs' := store rs n next in rank_start_loop fuel (n + 1) (u32 (next + v)) rank rs'.
Proof.
