Lemma sort_loop_S : forall fuel n ws rs syms,
  sort_loop (S fuel) n ws rs syms =
    let! w := load ws n in let! p := load rs w in let! rs' := store rs w (u32 (p + 1)) in
    let! syms' := ostore syms p n in sort_loop fuel (n + 1) ws rs' syms'.
Proof.
