Lemma zero_words : forall (rank1 rank2 : list Z) scale, zlen rank1 = 13 -> 1 <= scale <= 11 -> zlen rank2 = 13 ->
  (forall j, 0 <= j -> Znth j rank2 = if (0 <? j) && (j <=? scale) then 0 else Znth j rank1) ->
  map (Z_to_bv 64) rank2 = firstn 1 (map (Z_to_bv 64) rank1) ++ repeat (Z_to_bv 64 0) (Z.to_nat scale)
                             ++ skipn (1 + Z.to_nat scale) (map (Z_to_bv 64) rank1).
